{"cards": [{"node_code": "N_e9f20d98d41f4737", "definition": "研究铁路信号设备在运行维护阶段的保养策略、检修工艺、故障诊断方法及状态监测技术，旨在保障设备可靠性与行车安全。", "boundary": "本节点聚焦于信号设备的“维护”与“修复”过程。边界在于区分“日常维护/检修”与“设计/制造”（设计归器材与设备，制造归工厂）、“维护”与“测试”（测试侧重检测手段，检修侧重恢复功能）、“维护”与“干扰防护”（防护侧重预防外部影响，检修侧重内部故障处理）。若内容涉及信号设备的安装施工，通常归入工程实施或相关施工节点，若侧重安装后的调试与验收，可关联本节点。", "includes": ["信号设备的定期保养、预防性维护及故障检修流程", "信号设备故障诊断技术、状态监测及维修管理", "信号设备检修标准、工艺规范及维护人员作业指导"], "excludes": ["信号设备的新建工程设计、制造工艺流程", "信号设备的专用测试仪器原理（归测试设备节点）", "信号设备的外部电磁干扰防护技术（归干扰与防护节点）"], "sibling_distinctions": [{"other_code": "N_b1a2cfcbe0003e5d", "rule": "区分依据为对象与目的：本节点侧重利用测试手段进行故障排查和设备状态评估，核心是“修”与“养”；测试设备节点侧重测试仪器本身的原理、性能及专用工具。"}, {"other_code": "N_597159f8e73d7692", "rule": "区分依据为问题来源：本节点处理设备内部老化、磨损或故障；干扰与防护节点处理外部电磁、雷电等环境因素对设备的影响及防护措施。"}], "cross_boundary_rule": "若内容涉及“基于大数据的信号设备预测性维护”，若侧重算法模型可关联理论，但侧重维护策略与实施流程归本节点。"}, {"node_code": "N_597159f8e73d7692", "definition": "研究铁路信号设备在复杂电磁环境、雷电及机械振动等外部干扰下的稳定性，以及相应的屏蔽、接地、滤波等防护技术与标准。", "boundary": "本节点聚焦于信号设备抵御“外部干扰”的能力与措施。边界在于区分“干扰防护”与“设备内部故障”（内部故障归保养与检修）、“干扰防护”与“通信抗干扰”（若侧重通信链路抗干扰归通信，侧重信号控制逻辑抗干扰归本节点）。若内容涉及通用电子设备的电磁兼容（EMC）基础理论，归入通信、信号理论或通用电子类，本节点侧重铁路现场应用与具体防护工程。", "includes": ["信号设备的电磁兼容设计、屏蔽、接地与滤波技术", "雷电防护、过电压保护及机械振动防护措施", "铁路信号设备抗干扰标准、测试方法及现场整改案例"], "excludes": ["信号设备内部元器件老化或逻辑故障的检修（归保养与检修）", "通用通信系统的抗干扰技术（非铁路信号专用）", "信号设备的基础电磁场理论推导（归通信、信号理论）"], "sibling_distinctions": [{"other_code": "N_e9f20d98d41f4737", "rule": "区分依据为故障源：本节点针对外部环境（电磁、雷电、振动）导致的异常，侧重预防与防护；保养与检修针对设备内部状态，侧重修复与维护。"}, {"other_code": "N_26f890657055ce31", "rule": "区分依据为内容侧重：本节点侧重设备在恶劣环境下的生存能力与防护策略；器材与设备节点侧重设备本身的结构、参数及功能实现。"}], "cross_boundary_rule": "若内容涉及“信号设备防雷接地系统”，若侧重接地网设计与施工归本节点；若侧重接地材料特性归器材与设备。"}, {"node_code": "N_65e933b812e04814", "definition": "研究铁路信号设备（如信号机、转辙机、箱盒等）在铁路建筑限界内的安装位置、尺寸要求及安全距离，确保列车运行安全。", "boundary": "本节点聚焦于信号设备与铁路建筑空间关系的“几何约束”与“安全标准”。边界在于区分“建筑限界”与“设备安装工艺”（工艺归保养与检修或工程实施）、“建筑限界”与“线路设计”（线路限界归线路工程，本节点侧重信号设备在限界内的具体布置）。若内容涉及信号设备的结构设计以适配限界，归器材与设备；本节点侧重限界标准、计算及合规性检查。", "includes": ["铁路信号设备的建筑限界标准、尺寸规定及安全距离", "信号机、转辙机等设备的安装位置计算与限界校核", "信号设备与线路、桥梁、隧道等基础设施的空间关系规范"], "excludes": ["信号设备的具体机械结构设计（归器材与设备）", "铁路线路、桥梁、隧道的整体建筑限界设计（归线路或桥隧工程）", "信号设备的安装施工工艺流程（归保养与检修或工程实施）"], "sibling_distinctions": [{"other_code": "N_26f890657055ce31", "rule": "区分依据为关注点：本节点侧重设备在空间中的“位置”与“边界”合规性；器材与设备节点侧重设备本身的“结构”与“性能”。"}, {"other_code": "N_e9f20d98d41f4737", "rule": "区分依据为阶段：本节点涉及安装前的设计校核或安装后的位置检查；保养与检修侧重设备功能状态的维护。"}], "cross_boundary_rule": "若内容涉及“信号机安装高度与限界关系”，主挂载本节点；若涉及信号机内部结构如何适应该高度，可关联器材与设备。"}]}
